   853	static xmlNodePtr
   854	xmlXIncludeCopyNodeList(xmlXIncludeCtxtPtr ctxt, xmlDocPtr target,
   855	                        xmlDocPtr source, xmlNodePtr elem) {
   856	    xmlNodePtr cur, res, result = NULL, last = NULL;
   857	
   858	    if ((ctxt == NULL) || (target == NULL) || (source == NULL) ||
   859	        (elem == NULL))
   860	        return(NULL);
   861	    cur = elem;
   862	    while (cur != NULL) {
   863	        res = xmlXIncludeCopyNode(ctxt, target, source, cur);
   864	        if (res != NULL) {
